105	                signature.input(inputName, namePartOf(input.getValue().getName()));
106	            }
107	
108	            Map<String, TensorInfo> outputInfoMap = signatureEntry.getValue().getOutputsMap();
109	            for (Map.Entry<String, TensorInfo> output : outputInfoMap.entrySet()) {
110	                String outputName = output.getKey();
